var calc_output = [];
var age = parseFloat(age);
var choice = parseFloat(choice);
var resp_support = parseFloat(resp_support);
var imv = parseFloat(imv);
var vaso_meds = parseFloat(vaso_meds);
var lactate = parseFloat(lactate);
var map = parseFloat(map);
var platelets = parseFloat(platelets);
var inr = parseFloat(inr);
var ddimer = parseFloat(ddimer);
var gcs = parseFloat(gcs);
var fibrinogen = parseFloat(fibrinogen);

var resp_score;
if (choice == 0) {
    if(UOMSYSTEM == true) {
        var pao2 = parseFloat(pao2);
    }
    if (UOMSYSTEM == false) {
        var pao2 = parseFloat(pao2)/0.133;
    }
    var fio2 = parseFloat(fio2);

    var pf_ratio = pao2/(fio2/100);

    if (pf_ratio < 100 && resp_support == 2) {
        resp_score = 3;
    } else if (pf_ratio <= 200 && resp_support == 2) {
        resp_score = 2;
    } else if (pf_ratio < 400 && (resp_support == 1 || resp_support == 2)) {
        resp_score = 1;
    } else {
        resp_score = 0;
    }
} else if (choice == 1) {
    var spo2_check = parseFloat(spo2_check);
    if (spo2_check == 0) {
        resp_score = 0;
    } else if (spo2_check == 1) {
        var spo2 = parseFloat(spo2);
        var fio2 = parseFloat(fio2);
        var sf_ratio = spo2 / (fio2 / 100);

        if (sf_ratio < 148 && resp_support == 2) {
            resp_score = 3;
        } else if (sf_ratio <= 220 && resp_support == 2) {
            resp_score = 2;
        } else if (sf_ratio < 292 && (resp_support == 1 || resp_support == 2)) {
            resp_score = 1;
        } else {
            resp_score = 0;
        }
    }
}

var am_score;
if (age == 0) {
    if (map > 30) {
        am_score = 0;
    } else if (map >= 17) {
        am_score = 1;
    } else {
        am_score = 2;
    }
} else if (age == 1) {
    if (map > 38) {
        am_score = 0;
    } else if (map >= 25) {
        am_score = 1;
    } else {
        am_score = 2;
    }
} else if (age == 2) {
    if (map > 43) {
        am_score = 0;
    } else if (map >= 31) {
        am_score = 1;
    } else {
        am_score = 2;
    }
} else if (age == 3) {
    if (map > 44) {
        am_score = 0;
    } else if (map >= 32) {
        am_score = 1;
    } else {
        am_score = 2;
    }
} else if (age == 4) {
    if (map > 48) {
        am_score = 0;
    } else if (map >= 36) {
        am_score = 1;
    } else {
        am_score = 2;
    }
} else if (age == 5) {
    if (map > 51) {
        am_score = 0;
    } else if (map >= 38) {
        am_score = 1;
    } else {
        am_score = 2;
    }
}

var cardio_score = vaso_meds + lactate + am_score;

var coag_score = platelets + inr + ddimer + fibrinogen;
if (coag_score > 2) {
    coag_score = 2;
}

var score = resp_score + cardio_score + coag_score + gcs;

var result;
if (score >= 2 && cardio_score >= 1) {
    result = 'Meets septic shock criteria.';
} else if (score >= 2) {
    result = 'Meets sepsis criteria.';
} else {
    result = 'Does not meet sepsis criteria.';
}

calc_output.push({
    name: 'mini',
    value: score,
    value_text: 'points',
    message: result
});
calc_output.push({
